function esc(s) {
  return s.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

const tierTags = {
  major: { interests: ["business-strategy", "entrepreneurship"], skills: ["communication", "leadership", "strategic-thinking"], workStyles: ["collaborative", "people-focused", "analytical"] },
  specialized: { interests: ["business-strategy", "finance-investing"], skills: ["communication", "negotiation", "decision-making"], workStyles: ["analytical", "collaborative", "people-focused"] },
  emerging: { interests: ["business-strategy", "entrepreneurship", "technology"], skills: ["strategic-thinking", "creativity", "communication"], workStyles: ["collaborative", "creative", "analytical"] },
  interdisciplinary: { interests: ["business-strategy", "psychology", "communication"], skills: ["research", "communication", "critical-thinking"], workStyles: ["analytical", "collaborative", "people-focused"] },
  hidden: { interests: ["business-strategy", "entrepreneurship"], skills: ["organization", "communication", "persuasion"], workStyles: ["independent", "people-focused", "hands-on"] },
};

let out = `import { GrowthOutlook } from "../../../src/generated/prisma/client";

import { c } from "../career-builder";

/** Operations category — batch 13 of the 1,000+ career catalog. */
export const OPERATIONS_CAREERS = [
`;

for (const row of careers) {
  const [slug, title, tagline, summary, min, max, opts = {}] = row;
  const tags = tierTags[opts.tier ?? "specialized"];
  const lines = [`  c({`];
  lines.push(`    slug: "${slug}",`);
  lines.push(`    title: "${esc(title)}",`);
  lines.push(`    tagline: "${esc(tagline)}",`);
  lines.push(`    summary: "${esc(summary)}",`);
  lines.push(`    salaryMin: ${min},`);
  lines.push(`    salaryMax: ${max},`);
  if (opts.anchor) lines.push(`    anchor: true,`);
  if (opts.featured) lines.push(`    featured: true,`);
  if (opts.tier) lines.push(`    tier: "${opts.tier}",`);
  if (opts.growth) lines.push(`    growthOutlook: GrowthOutlook.${opts.growth},`);
  if (opts.companies) lines.push(`    exampleCompanies: [${opts.companies.map((x) => `"${x}"`).join(", ")}],`);
  if (opts.aliases) lines.push(`    aliases: [${opts.aliases.map((x) => `"${esc(x)}"`).join(", ")}],`);
  if (opts.related) lines.push(`    related: [${opts.related.map((x) => `"${x}"`).join(", ")}],`);
  lines.push(`    interests: [${tags.interests.map((x) => `"${x}"`).join(", ")}],`);
  lines.push(`    skills: [${tags.skills.map((x) => `"${x}"`).join(", ")}],`);
  lines.push(`    workStyles: [${tags.workStyles.map((x) => `"${x}"`).join(", ")}],`);
  lines.push(`    commonTasks: "${esc(opts.tasks ?? "")}",`);
  lines.push(`    downsides: "${esc(opts.downsides ?? "")}",`);
  lines.push(`  }),`);
  out += lines.join("\n") + "\n";
}

out += `];\n`;

const outPath = path.join(__dirname, "../data/categories/operations.ts");
fs.mkdirSync(path.dirname(outPath), { recursive: true });
fs.writeFileSync(outPath, out);
console.log(`Generated ${careers.length} operations careers → ${outPath}`);
